begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();o uuid:=gen_random_uuid();sa uuid;sb uuid;so uuid;pid uuid:=gen_random_uuid();did uuid:=gen_random_uuid();cid uuid;k uuid:=gen_random_uuid();rid uuid;other_draft uuid:=gen_random_uuid();fid uuid;oid uuid;r jsonb;f jsonb;failed boolean;
begin
 insert into auth.users(id,email_confirmed_at) values(a,now()),(b,now()),(o,now());insert into memocious_private.admin_users(user_id,role) values(o,'owner');
 sa:=public.memocious_session_open(repeat('1',64),repeat('2',64),a,'customer','fixture','1');sb:=public.memocious_session_open(repeat('3',64),repeat('4',64),b,'customer','fixture','1');so:=public.memocious_session_open(repeat('5',64),repeat('6',64),o,'admin','fixture','1');perform public.memocious_session_mfa(so,repeat('7',64),repeat('8',64),'fixture');
 update memocious.site_settings set value='true' where key='policies_approved';
 select id into cid from memocious.categories where slug='gift-hampers';
 insert into memocious.products(id,slug,name,active,publication_state,customizable,price_paise) values(pid,'submit-fixture','Submission fixture',true,'published',true,0);
 insert into memocious.product_categories(product_id,category_id) values(pid,cid);insert into memocious.product_images(product_id,public_path,alt,sanitized_at,published_at) values(pid,'/media/submit.webp','Fixture',now(),now());perform memocious_private.refresh_publication();
 f:=jsonb_build_object('budgetMinPaise',0,'budgetMaxPaise',10000,'giftTypeId',cid,'occasionId',null,'recipient','','message','Private message','productId',pid,'pricingVersion',1,'options','[]'::jsonb,'quantity',1,'requestedDate',((now() at time zone 'Asia/Kolkata')::date+10)::text,'contact',jsonb_build_object('name','Test','phone','447700900123','email','','city','Test','pincode','400001'));
 execute 'set local role service_role';perform public.memocious_builder_draft(sa,'create',did,0,2,8,f);
