 failed:=false;begin perform public.memocious_builder_submit(sa,did,1,k,true,true);exception when serialization_failure then failed:=true;end;if not failed then raise exception 'Stale draft submitted';end if;
 r:=public.memocious_builder_submit(sa,did,2,k,true,true);rid:=(r->>'id')::uuid;
