 failed:=false;begin perform public.memocious_builder_submit(so,did,2,k,true,true);exception when invalid_authorization_specification then failed:=true;end;if not failed then raise exception 'Admin submitted as customer';end if;
 perform public.memocious_builder_draft(sa,'create',other_draft,0,2,8,f);
 failed:=false;begin perform public.memocious_builder_submit(sa,other_draft,1,k,true,true);exception when serialization_failure then failed:=true;end;if not failed then raise exception 'Key reused across drafts';end if;
 if public.memocious_builder_submit(sa,did,2,k,true,true) is distinct from r or public.memocious_builder_submit(sa,did,2,gen_random_uuid(),true,true,true) is distinct from r then raise exception 'Replay differs';end if;
 if (select count(*) from memocious.custom_requests where draft_id=did)<>1 or (select count(*) from memocious.consent_records where custom_request_id=rid)<>1 or (select count(*) from memocious.phase2_events where entity_id=rid)<>1 then raise exception 'Duplicated effects';end if;
 if (select draft_id is not null or custom_request_id<>rid or status<>'attached' from memocious.request_uploads where id=fid) then raise exception 'File not transferred';end if;perform public.memocious_builder_file(sa,fid,'read');perform public.memocious_builder_file(so,fid,'read');
 if public.memocious_privacy(sa,'export')->'customRequests'->0->>'code' is distinct from r->>'code' or jsonb_array_length(public.memocious_privacy(sb,'export')->'customRequests')<>0 or public.memocious_privacy(sa,'export')->'builderFiles'->0->>'download' is distinct from '/api/builder/files/'||fid then raise exception 'Custom export incorrect';end if;
