 if public.memocious_custom_requests(sa)->'records'->0 ? 'history' then raise exception 'Internal history leak';end if;
 execute 'reset role';
 failed:=false;begin update memocious.custom_requests set immutable_snapshot='{}' where id=rid;exception when insufficient_privilege then failed:=true;end;if not failed then raise exception 'Snapshot mutable';end if;
end $$;
